package sandbox

import (
	"encoding/binary"
	"errors"
	"fmt"
	"runtime"
	"unsafe"

	"golang.org/x/sys/unix"
)

// The socket filter is written out as BPF rather than generated by a
// library, because what it has to get right is what such libraries leave to
// their caller:
//
//   - A filter is written for one system call table. A 64-bit x86 process can
//     also make 32-bit calls (int $0x80), which have other numbers, so a
//     filter that only knows the native table lets socket(2) through that
//     way. Calls from any other table are refused here.
//   - The kernel reads socket(2)'s arguments as 32-bit ints and ignores the
//     upper half of the register. A filter comparing all 64 bits is passed by
//     setting any upper bit, so only the lower half is compared.
//
// Both were ways around an earlier version of this filter.

// seccomp_data, which the filter reads: the call number, the table it is
// from (an AUDIT_ARCH value), and six 64-bit arguments from offset 16.
const (
	seccompNr   = 0
	seccompArch = 4
	seccompArgs = 16
)

// x32Bit marks a call from the x32 table, which shares AUDIT_ARCH_X86_64.
const x32Bit = 0x40000000

// 32-bit x86's numbers for the calls that make sockets, for a 64-bit kernel
// running a 32-bit program. socketcall carries the family in memory, where a
// filter cannot look, so it goes whole.
const (
	i386Socketcall   = 102
	i386Socket       = 359
	i386IoUringSetup = 425
)

// nativeArch is the AUDIT_ARCH of this build's system calls. Only
// architectures whose socket(2) is a call of its own are listed: where it
// goes through socketcall there is nothing a filter can check.
func nativeArch() (uint32, error) {
	switch runtime.GOARCH {
	case "amd64":
		return unix.AUDIT_ARCH_X86_64, nil
	case "arm64":
		return unix.AUDIT_ARCH_AARCH64, nil
	case "riscv64":
		return unix.AUDIT_ARCH_RISCV64, nil
	case "loong64":
		return unix.AUDIT_ARCH_LOONGARCH64, nil
	}
	return 0, fmt.Errorf("the sandbox cannot filter sockets on linux/%s", runtime.GOARCH)
}

const (
	retAllow = unix.SECCOMP_RET_ALLOW
	retKill  = unix.SECCOMP_RET_KILL_PROCESS
	retEPERM = unix.SECCOMP_RET_ERRNO | uint32(unix.EPERM)
	retNoSys = unix.SECCOMP_RET_ERRNO | uint32(unix.ENOSYS)
)

// load puts the 32-bit word at off in the accumulator.
func load(off uint32) unix.SockFilter {
	return unix.SockFilter{Code: unix.BPF_LD | unix.BPF_W | unix.BPF_ABS, K: off}
}

// ifNot skips the next skip instructions unless the accumulator equals k.
func ifNot(k uint32, skip uint8) unix.SockFilter {
	return unix.SockFilter{Code: unix.BPF_JMP | unix.BPF_JEQ | unix.BPF_K, Jf: skip, K: k}
}

func ret(action uint32) unix.SockFilter {
	return unix.SockFilter{Code: unix.BPF_RET | unix.BPF_K, K: action}
}

// argLow is the offset of the lower 32 bits of argument n.
func argLow(n uint32) uint32 {
	off := seccompArgs + 8*n
	if binary.NativeEndian.Uint16([]byte{1, 0}) != 1 {
		off += 4 // big-endian: the upper half comes first
	}
	return off
}

// socketFilter is the seccomp program for p on a system whose native call
// table is arch.
//
// With the network off, socket(2) fails with EPERM for every family except
// netlink (kernel-local: listing interfaces, which many tools do at startup,
// needs it) and, if allowed, Unix: a default-deny list, so families such as
// Bluetooth, CAN or VSOCK cannot carry data out either.
//
// Unix sockets are denied unless allowed: Landlock cannot restrict connecting
// to one by path before ABI 9, which few kernels have. socketpair(2) still
// works.
//
// NETLINK_USERSOCK, which is userspace-to-userspace IPC, is always denied.
//
// io_uring can create sockets without socket(2), so it is denied whenever
// any socket is.
//
// A 32-bit x86 program on a 64-bit kernel keeps running, without sockets or
// io_uring. Calls from any other foreign table kill the command.
func socketFilter(p Policy, arch uint32) []unix.SockFilter {
	restricted := !p.Network || !p.UnixSockets
	uring := uint32(retAllow)
	if restricted {
		uring = retEPERM
	}

	f := []unix.SockFilter{load(seccompArch)}
	if arch == unix.AUDIT_ARCH_X86_64 {
		f = append(f,
			ifNot(unix.AUDIT_ARCH_I386, 8),
			load(seccompNr),
			ifNot(i386Socketcall, 1), ret(retEPERM),
			ifNot(i386Socket, 1), ret(retEPERM),
			ifNot(i386IoUringSetup, 1), ret(uring),
			ret(retAllow),
		)
	}
	f = append(f,
		unix.SockFilter{Code: unix.BPF_JMP | unix.BPF_JEQ | unix.BPF_K, Jt: 1, K: arch},
		ret(retKill),
		load(seccompNr),
	)
	if arch == unix.AUDIT_ARCH_X86_64 {
		f = append(f,
			unix.SockFilter{Code: unix.BPF_JMP | unix.BPF_JGE | unix.BPF_K, Jf: 1, K: x32Bit},
			ret(retNoSys),
		)
	}
	f = append(f,
		ifNot(unix.SYS_IO_URING_SETUP, 1), ret(uring),
		unix.SockFilter{Code: unix.BPF_JMP | unix.BPF_JEQ | unix.BPF_K, Jt: 1, K: unix.SYS_SOCKET},
		ret(retAllow),

		// socket(family, type, protocol)
		load(argLow(0)),
		ifNot(unix.AF_NETLINK, 3),
		load(argLow(2)),
		ifNot(unix.NETLINK_USERSOCK, 1), ret(retEPERM),
		load(argLow(0)),
	)
	switch {
	case !p.Network:
		f = append(f, ifNot(unix.AF_NETLINK, 1), ret(retAllow))
		if p.UnixSockets {
			f = append(f, ifNot(unix.AF_UNIX, 1), ret(retAllow))
		}
		f = append(f, ret(retEPERM))
	case !p.UnixSockets:
		f = append(f, ifNot(unix.AF_UNIX, 1), ret(retEPERM), ret(retAllow))
	default:
		f = append(f, ret(retAllow))
	}
	return f
}

// denySockets installs socketFilter(p) on every thread of this process.
func denySockets(p Policy) error {
	arch, err := nativeArch()
	if err != nil {
		return err
	}
	filter := socketFilter(p, arch)
	if err := unix.Prctl(unix.PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0); err != nil {
		return fmt.Errorf("no_new_privs: %w", err)
	}
	prog := unix.SockFprog{Len: uint16(len(filter)), Filter: &filter[0]}
	// TSYNC: the Go runtime has other threads, and the exec that follows
	// must not happen on one the filter missed.
	r, _, errno := unix.Syscall(unix.SYS_SECCOMP, unix.SECCOMP_SET_MODE_FILTER,
		unix.SECCOMP_FILTER_FLAG_TSYNC, uintptr(unsafe.Pointer(&prog)))
	runtime.KeepAlive(filter)
	switch {
	case errno != 0:
		return errno
	case r != 0:
		return errors.New("could not apply the filter to every thread")
	}
	return nil
}
